 public static void VerifyRuntime(){
  Check(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var mind=god.GetComponent<CreatureCuriosity>();var world=slice.GetComponentInChildren<VillageResources>();var nav=world.Navigation;Check(!nav.TreeNavigationPending,"Wait for navigation");var site=god.GetComponent<CreatureConstructionLearning>().sites[0];var saved=site.Capture();var recipe=site.Recipe;bool wasPaused=site.Paused;var field=typeof(QuestSlice).GetField("state",F);var original=(SliceState)field.GetValue(slice);var people=world.Gatherers;var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var gp=god.transform.position;var gr=god.transform.rotation;var hands=(CarryItem[])typeof(QuestSlice).GetField("held",F).GetValue(slice);Check(hands.All(h=>h==null),"Release hand items");var cooldowns=god.Targets.Where(t=>t.affordance!=null).ToDictionary(t=>t.affordance,t=>t.affordance.cooldown);var ideas=god.Targets.Where(t=>t.GetComponent<ConstructionInspiration>()!=null).ToArray();var active=ideas.Select(t=>t.gameObject.activeSelf).ToArray();var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100,crops=100,hunger=.1f};var pointer=typeof(QuestSlice).GetMethod("BuildAttentionPointer",F);var anchor=site.blocks.First(b=>b.Shape==ConstructionShape.Brick);var at=ConstructionPatterns.Plan(BuildRecipe.Arch)[0].position;
