   eventCount=test.Hybrid.Evidence.nextId;Point(true,false);Point(true,true,true,next);Point(false,true,true,next);Check(test.Hybrid.Evidence.nextId==eventCount&&hands[1]==null,"Dragging pointer fired gesture");Point(true,false);Point(true,true,true,anchor,false);Point(false,true);Check(test.Hybrid.Evidence.nextId==eventCount,"Lost tracking fired gesture");Point(true,false);Point(false,true,true,anchor,true,true);Check(test.Hybrid.Evidence.nextId==eventCount,"Blocked/menu input fired gesture");Point(true,false);typeof(QuestSlice).GetMethod("OnApplicationPause",F).Invoke(slice,new object[]{true});Check(typeof(QuestSlice).GetField("pendingBuildTap",F).GetValue(slice)==null,"Suspension retained pending press");typeof(QuestSlice).GetMethod("OnApplicationPause",F).Invoke(slice,new object[]{false});palette.Process(new Ray(Camera.main.transform.position,Camera.main.transform.forward),false,true,false,.1f,false);Point(false,true);Check(test.Hybrid.Evidence.nextId==eventCount,"Resume fired an old tap");site.Paused=false; // Simulate reapplies this scene flag on the next resumed frame.
   test.paused=true;Check(!god.PointToPlayerBuild(anchor),"Paused gesture accepted");test.paused=false;
   var facing=god.transform.rotation;god.transform.rotation=Quaternion.Euler(0,180,0)*facing;test.Hybrid.time+=9;Check(!god.PointToPlayerBuild(anchor),"Unseen gesture accepted");god.transform.rotation=facing;int known=test.Building.observed;test.Building.observed=0;Check(!god.PointToPlayerBuild(anchor),"Unknown form commanded");test.Building.observed=known;
   Check(Point(true,false,false),"Desktop F gesture not handled");eventCount=test.Hybrid.Evidence.nextId;Point(true,true,false);Check(test.Hybrid.Evidence.nextId==eventCount&&hands[1]==null,"Held desktop F repeated or grabbed");typeof(QuestSlice).GetMethod("Save",F).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",F).Invoke(slice,null);test=(SliceState)field.GetValue(slice);god.NewSeason();world.ResetWorld();site.Recipe=BuildRecipe.Arch;site.Restore(test.construction);Check(test.Valid()&&god.IsPlayerBuildAnchor(anchor)&&Bias(next)==0,"Native save lost provenance or replayed transient invitation");test.developmentFocus=test.observeWithoutFoodWork=true;
   foreach(var idea in ideas)idea.gameObject.SetActive(false);foreach(var a in cooldowns.Keys)a.cooldown=a==next.GetComponent<CreatureAffordance>()?0:test.Hybrid.time+100000;Check(god.PointToPlayerBuild(anchor),"Fresh gesture after reload failed: paused="+test.paused+" suspended="+typeof(CreatureHybrid).GetField("suspended",F).GetValue(god)+" seen="+god.CanSeeCue(anchor.GetComponent<HybridTarget>())+" anchor="+god.IsPlayerBuildAnchor(anchor)+" recipe="+site.Recipe+" known="+test.Building.Knows(site.Recipe)+" complete="+site.RecipeComplete+" sitePaused="+site.Paused+" available="+next.GetComponent<CreatureAffordance>().Available);offered=test.Hybrid.Evidence.events.Last(e=>e.kind==EvidenceKind.GuidanceOffered).id;god.Perceive();var candidates=(System.Collections.Generic.List<CreatureCandidate>)typeof(CreatureHybrid).GetField("candidates",F).GetValue(god);Check(candidates.Any(c=>c.target==next.GetComponent<HybridTarget>().id&&c.guidance>.8f&&c.guidanceEvidenceId==offered),"No guidance-attributed construction candidate");int built=mind.built;god.Tick(.05f);Check(god.Owner==CreatureHybrid.ActionOwner.Curiosity&&test.Hybrid.intention.source==EvidenceSource.PlayerGuidance&&test.Hybrid.intention.action==CreatureAction.ConstructionPlay,"Coordinator did not choose renewed build");int started=test.Hybrid.intention.evidenceId;test.Hybrid.time+=9;Check(god.PointToPlayerBuild(anchor)&&test.Hybrid.intention.evidenceId==started&&god.Owner==CreatureHybrid.ActionOwner.Curiosity,"New gesture interrupted or relabeled current action");for(int i=0;i<2000&&mind.built==built;i++){god.Tick(.05f);site.Advance(.02f);}Check(mind.built==built+1&&next.Attached&&next.creatureBuilt&&test.Hybrid.receipt.eligible&&test.Hybrid.receipt.action==CreatureAction.ConstructionPlay,"Native renewed build did not complete");var begun=test.Hybrid.Evidence.events.First(e=>e.id==started);Check(begun.relatedId==offered&&begun.source==EvidenceSource.PlayerGuidance&&test.placeContributions.records.Count(r=>r.actor=="creature")==1&&god.Feedback(true)&&!god.Feedback(true),"Action causality, placement source or one-shot teaching wrong");Check(test.Valid(),"Renewed construction evidence invalid");
   Debug.Log("BWVR_BUILD_ATTENTION_PASS: recorded player-only anchor, expired renewal, Quest tap/hold, desktop edge, drag/tracking/menu/pause/visibility/unknown-form guards, cooldown, no fabricated work/lesson, native save without replay, guidance-causal utility-selected construction and busy ownership preserved");
  }finally{god.Interrupt("Build attention QA complete");pointer.Invoke(slice,new object[]{1,false,false,true,true,null,.05f,true});for(int i=0;i<2;i++){if(hands[i]!=null){hands[i].held=false;hands[i].GetComponent<Collider>().enabled=true;hands[i]=null;}}foreach(var b in site.blocks)b.Item.held=false;site.Recipe=recipe;site.Restore(saved);site.Paused=wasPaused;field.SetValue(slice,original);god.NewSeason();world.ResetWorld();foreach(var p in cooldowns)p.Key.cooldown=p.Value;for(int i=0;i<ideas.Length;i++)ideas[i].gameObject.SetActive(active[i]);god.transform.SetPositionAndRotation(gp,gr);god.GetComponent<IslandNavigator>().ResetRoute();for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}slice.SetSanctuaryOpen(false);Physics.SyncTransforms();}
